import { expect, type Page } from "@playwright/test";

export const getLocators = (page: Page) => {
  const inspectorCanvas = page.getByTestId("inspector-canvas");
  const flowNodes = page.getByTestId("node").or(page.getByTestId("node-selected"));
  const canvasFlowNodes = inspectorCanvas
    .getByTestId("node")
    .or(inspectorCanvas.getByTestId("node-selected"));

  return {
    inspectorCanvas,
    canvas: page.getByTestId("canvas"),
    flowNodes,
    selectedNodes: page.getByTestId("node-selected"),
    selectedEdges: page.getByTestId("edge-selected"),
    flowNode: (nodeName: string) => canvasFlowNodes.filter({ hasText: nodeName }),
    flowName: (flowName: string) => inspectorCanvas.getByText(flowName),
    noActiveFlowPlaceholder: page.getByText("No flow is currently active"),
    flowsErrorLabel: page.getByText("Failed to load flows"),
    zoomInButton: page.getByRole("button", { name: "Zoom in" }),
    zoomOutButton: page.getByRole("button", { name: "Zoom out" }),
    zoomTo100Button: page.getByRole("button", { name: "Zoom to 100%" }),
    fitToCanvasButton: page.getByRole("button", { name: "Fit to canvas" }),
  };
};

export const actions = (page: Page) => {
  const locators = getLocators(page);

  return {
    zoomIn: async () => {
      await locators.zoomInButton.click();
    },
    zoomOut: async () => {
      await locators.zoomOutButton.click();
    },
    zoomTo100: async () => {
      await locators.zoomTo100Button.click();
    },
    fitToCanvas: async () => {
      await locators.fitToCanvasButton.click();
    },
  };
};

export const assertions = (page: Page) => {
  const locators = getLocators(page);

  return {
    inspectorCanvasIsVisible: async () => {
      await expect(
        locators.inspectorCanvas,
        "Inspector canvas should be visible when Inspect is on",
      ).toBeVisible();
    },
    inspectorCanvasIsHidden: async () => {
      await expect(
        locators.inspectorCanvas,
        "Inspector canvas should be hidden when Inspect is off",
      ).toBeHidden();
    },
    flowPanelShowsNoActiveFlow: async () => {
      await expect(
        locators.noActiveFlowPlaceholder,
        "Flow panel should show the no-active-flow placeholder",
      ).toBeVisible();
    },
    canvasWithNodesIsVisible: async () => {
      await expect(locators.canvas, "Flow canvas should be visible").toBeVisible();
      await expect(
        locators.flowNodes.first(),
        "At least one flow node should be visible",
      ).toBeVisible({ timeout: 10000 });
    },
    flowNodeIsVisible: async (nodeName: string) => {
      await expect(
        locators.flowNode(nodeName),
        `Flow node "${nodeName}" should be visible`,
      ).toBeVisible({ timeout: 10000 });
    },
    activeFlowNameIsVisible: async (flowName: string) => {
      await expect(
        locators.flowName(flowName),
        `Active flow name "${flowName}" should be visible`,
      ).toBeVisible();
    },
    flowCanvasIsReplacedByDetails: async () => {
      await expect(
        locators.canvas,
        "Flow canvas should be hidden when the event details panel is shown",
      ).toBeHidden();
    },
    flowCanvasIsVisible: async () => {
      await expect(locators.canvas, "Flow canvas should be visible").toBeVisible();
    },
    flowsErrorIsVisible: async () => {
      await expect(
        locators.flowsErrorLabel,
        "Failed to load flows error should be visible",
      ).toBeVisible();
    },
    zoomPercentageIs: async (expected: string) => {
      await expect(locators.zoomTo100Button, `Zoom percentage should read ${expected}`).toHaveText(
        expected,
      );
    },
    zoomPercentageChangedFrom: async (initial: string) => {
      await expect
        .poll(
          async () => {
            const current = (await locators.zoomTo100Button.textContent()) ?? "";
            return current !== initial && current.length > 0;
          },
          { message: `Zoom percentage should change from ${initial}` },
        )
        .toBe(true);
    },
    selectedNodeCountAtLeast: async (count: number) => {
      await expect
        .poll(async () => (await locators.selectedNodes.count()) >= count, {
          message: `At least ${count} selected canvas node(s) should be visible`,
          timeout: 10000,
        })
        .toBe(true);
    },
    highlightedEdgeCountAtLeast: async (count: number) => {
      await expect
        .poll(async () => (await locators.selectedEdges.count()) >= count, {
          message: `At least ${count} highlighted canvas edge(s) should be visible`,
          timeout: 10000,
        })
        .toBe(true);
    },
  };
};
